"Glutwicht": "熾火の小鬼",
"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "犬がいなくなった途端、狐が厩の周りをうろつく。草原へ追い返せ",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "猪が農民の作物を食い荒らす。蓄えのない冬は我らの終わりだ",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "草原の外れで怒りの石が光る。その怒りが獣を狂わせる – 砕け",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "バオが寄越してくれてよかった。山賊が森の道で商人を襲っている。追い払え",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "ここの猪は剛毛の代わりに棘を持つ。罠も – 罠師も引き裂く",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "森の奥で巨大蜘蛛が道に巣を張る。必要なら焼き払え",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "森の中央に棘の石が生えている。その蔓があらゆる木を締め殺す。壊せ",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "ハーゲンの差し金か？なら来い、オークどもがもう柵の前だ。奴らの軍勢を削れ",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "オークはハイエナを犬のように飼い、斥候にけしかける。群れを片付けろ",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "イドリスの紹介か？神々はサフラに優しい。コブラがどの水場にも潜んでいる",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "あのガラガラ音が聞こえるか？ガラガラヘビだ。何百匹も。隊商はもう出発できない",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "霜の峰で家ほどもあるイエティが目撃された。証拠に毛皮を持ってこい",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "寒さが引かなくなってからマンモスが荒れ狂い、備蓄小屋を踏み潰す",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "静寂の石が立つ所では、あらゆる歌が途絶える。頂に音を取り戻せ",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "最後にして最強のソウルストーン。それを壊せば石の成長は止まる",
"Hunde aus der Asche": "灰より来たる犬",
"Diebe im Zwielicht": "薄暮の盗賊",
"Wölfe aus dem Nebel": "霧より来たる狼",
"Die bleichen Geweihe": "青白き角",
"Nachthirsche rennen mit leuchtenden Geweihen gegen unsere Zäune, als jage sie etwas. Halte sie auf": "光る角の夜鹿が何かに追われるように柵へ突っ込んでくる。止めろ",
"Die Leitwölfe": "群れの長",
"Jedes Nebelrudel folgt einem Nachtleitwolf. Ohne ihn zerstreut sich das Rudel im Dunst": "霧の群れはどれも夜の群れの長に従う。長がいなければ群れは霧の中に散る",
"Keiler im Mondkraut": "月草の猪",
"Glut im Aschewald": "灰の森の熾火",
"Räuber in der Asche": "灰の中の盗賊",
"Glühende Hauer": "燃える牙",
"Die Keiler hier tragen Glut im Borstenkamm. Wo sie sich reiben, fängt das Unterholz Feuer": "ここの猪はたてがみに熾火を宿す。体をこすりつけた茂みが燃え上がる",
"Schützen im Rauch": "煙の中の射手",
"Aus dem Rauch schießen Rußschützen, bevor man sie sieht. Hol sie aus den verbrannten Kronen": "煤の射手は姿を見せる前に煙の中から射ってくる。焼けた梢から引きずり出せ",
"Graue Netze": "灰色の網",
"Zwei Steine der Gier locken die Räuber an wie Glut die Motten. Zerschlage sie": "2つの強欲の石が熾火に集まる蛾のように盗賊を引き寄せる。砕け",
"Rußgraue Jäger": "煤色の狩人",
"Rußluchse sind in der Asche unsichtbar. Unsere Köhler kommen nicht mehr heim. Sei wachsamer als sie": "煤の山猫は灰の中で見えない。炭焼きたちが帰ってこない。奴らより用心しろ",
"Kohlenbären": "炭の熊",
"Knochen im Sand": "砂の中の骨",
"Ascan schickt dich? Dann komm, die Beinbrecher stehen schon vor unserem Ring. Brich ihre Reihen": "アスカンの紹介か？なら来い、骨砕きどもがもう環の前だ。隊列を崩せ",
"Aashyänen": "屍肉のハイエナ",
"Die Hyänen folgen den Beinbrechern und fressen, was diese liegen lassen. Erledige die Meute": "ハイエナは骨砕きの後をつけ、残したものを喰らう。群れを片付けろ",
"Die Knochenruferinnen": "骨呼びたち",
"Die Ruferinnen singen die Gebeine aus dem Sand. Ohne ihren Gesang bleiben die Toten liegen": "骨呼びたちは歌で砂から骨を呼び起こす。歌がなければ死者は眠ったまま",
"Zwei schwarze Steine ragen aus den Dünen, und die Knochen sammeln sich darum. Nimm ihnen ihre Mitte": "砂丘から黒い石が2つ突き出し、骨がその周りに集まる。その中心を奪え",
"Bleiche Stachel": "青白い針",
"Die Knochenhauptmänner": "骨の隊長たち",
"Die Beinbrecher gehorchen Hauptmännern in alten Rüstungen. Fällst du sie, zerfällt das Heer": "骨砕きどもは古い鎧の隊長に従う。倒せば軍勢は崩れる",
"Ein Stein der Asche verbrennt die Wüste von innen. Lösch ihn aus, bevor nur Staub bleibt": "灰の石が砂漠を内側から焼く。塵しか残らなくなる前に消せ",
"Rot am Horizont": "地平の赤",
"Ossian hat recht, dich zu schicken. Blutoger stampfen jede Nacht gegen unsere Inseln. Halte sie fern": "オシアンが寄越したのは正しい。血のオーガが毎晩島に押し寄せる。寄せつけるな",
"Wargrudel der Steppe": "草原のワーグの群れ",
"Steppenwargs jagen in großen Rudeln durch das rote Gras. Jag das Rudel, bevor es uns jagt": "草原のワーグは赤い草の中を大群で狩る。奴らに狩られる前に狩れ",
"Blutdämonen": "血の悪魔",
"Aus den roten Tümpeln steigen Blutdämonen. Treib sie zurück in die Tiefe": "赤い淀みから血の悪魔が湧き出す。深みへ追い返せ",
"Die Steine der Glut heizen die Tümpel auf, bis sie kochen. Lösche sie aus": "熾火の石が淀みを煮え立たせる。消せ",
"Blutmäuler": "血顎たち",
"Blutmäuler bewachen die Tümpel der Dämonen. Wer sie besiegt, kann den Quellen nahe kommen": "血顎は悪魔の淀みを守る。倒した者だけが泉に近づける",
"Die Klippenfeste": "崖の砦",
"Kobras im Fels": "岩のコブラ",
"Das Rasseln in der Nacht": "夜のガラガラ音",
"Hörst du das Rasseln an den Klippen? Nachtrassler. Hunderte. Keiner traut sich mehr auf die Pfade": "崖のガラガラ音が聞こえるか？夜のガラガラヘビだ。何百匹も。もう誰も小道を通れない",
"Moorpythons": "沼の大蛇",
"Im Schwarzmoor würgen Pythons ganze Boote unter Wasser. Wer dort Torf sticht, kommt nicht wieder": "黒の沼では大蛇が船ごと水中へ引きずり込む。泥炭を掘りに行った者は戻らない",
"Panther im Nebel": "霧の豹",
"Die Nebelpanther jagen für die Moornagas. Mach das Moor wieder sicher": "霧の豹は沼のナーガのために狩る。沼を再び安全にしろ",
