"Schützen im Dickicht": "茂みの射手",
"Aus den Baumkronen schießen Banditen auf alles, was sich bewegt. Hol sie herunter": "山賊が木の上から動くもの全てを射ってくる。引きずり下ろせ",
"Netz der Spinnen": "蜘蛛の巣",
"Zwei Steine der Gier locken Banditen an wie Gold die Diebe. Zerschlage sie": "二つの強欲の石が金が盗賊を呼ぶように山賊を引き寄せる。砕け",
"Lautlose Jäger": "音なき狩人",
"Luchse reißen unsere Späher, ohne dass einer sie kommen sieht. Sei wachsamer als sie": "山猫が誰にも気付かれず斥候を襲う。奴らより用心しろ",
"Der Banditenfürst": "山賊の頭領",
"Der Braunbär": "ヒグマ",
"Ein Rudel Braunbären hat den Holzfällerpfad besetzt. Sie sind stark, sei vorsichtig": "ヒグマの群れが木こりの道を占拠した。強いので気をつけろ",
"Krieg in der Rostschlucht": "錆の峡谷の戦い",
"Orks vor der Talwacht": "谷の見張り所のオーク",
"Hyänen der Orks": "オークのハイエナ",
"Die Schamanen": "シャーマンたち",
"Ihre Schamanen rufen Flüche über das Tal. Ohne sie verlieren die Orks ihren Mut": "奴らのシャーマンが谷に呪いをかける。彼らがいなければオークは士気を失う",
"Die Orks beten schwarze Steine an. Nimm ihnen ihre Götzen": "オークは黒い石を崇めている。偶像を奪え",
"Stachel im Sand": "砂の中の毒針",
"In den Felsspalten nisten Riesenskorpione. Ihr Gift lähmt einen Ochsen. Räum die Spalten": "岩の裂け目に大蠍が巣くう。毒は牛をも麻痺させる。裂け目を掃討しろ",
"Der Ork-Hauptmann": "オークの隊長",
"Ohne ihre Hauptmänner sind die Orks nur ein wilder Haufen. Finde sie": "隊長がいなければオークはただの烏合の衆だ。見つけ出せ",
"Der Stein der Asche verbrennt das Tal von innen. Lösch ihn aus, bevor nur Staub bleibt": "灰の石が谷を内側から焼いている。塵しか残らなくなる前に消せ",
"Asche über dem Ödland": "荒野に降る灰",
"Oger im Aschenfeld": "灰の野のオーガ",
"Thrak hatte recht, dich zu schicken. Oger plündern unser Lager jede Nacht. Halte sie fern": "スラックがお前を送ったのは正解だ。オーガが毎晩野営地を荒らす。追い払え",
"Wargrudel": "ワーグの群れ",
"Wargs folgen den Ogern und fressen, was diese übrig lassen. Jag das Rudel": "ワーグはオーガの後を追い残り物を漁る。群れを狩れ",
"Dämonen im Ödland": "荒野の悪魔",
"Aus den Rissen im Ödland steigen Dämonen. Treib sie zurück in die Tiefe": "荒野の裂け目から悪魔が湧き出る。深みへ追い返せ",
"Die Steine der Glut lassen das Ödland brennen. Lösche sie aus": "熾火の石が荒野を燃やしている。消し去れ",
"Höllenhunde": "ヘルハウンド",
"Dreiköpfige Hunde bewachen die Risse. Wer sie besiegt, kann den Rissen nahe kommen": "三つ首の犬が裂け目を守る。倒せば裂け目に近づける",
"Die Oase im Süden": "南のオアシス",
"Kobras in der Wüste": "砂漠のコブラ",
"Das Rasseln im Sand": "砂の中のガラガラ音",
"Im Dschungel würgen Pythons ganze Ochsen. Wer dort Holz schlägt, kommt nicht wieder": "密林ではニシキヘビが牛を丸ごと絞め殺す。そこで木を伐る者は戻らない",
"Schwarze Panther": "黒豹",
"Die Panther der Nagas jagen in der Nacht. Mach den Dschungel wieder sicher": "ナーガの豹は夜に狩る。密林を再び安全にしろ",
"Eis im Norden": "北の氷",
"Eiswölfe": "氷狼",
"Hakim hat dich geschickt? Gut. Eiswölfe umkreisen unser Lager, sie riechen jede Schwäche": "ハキムの差し金か？よし。氷狼が野営地を囲み、どんな弱みも嗅ぎつける",
"Der Yeti": "イエティ",
"Zwei Steine des Frostes lassen den Gipfel nie mehr tauen. Zerschlage sie": "二つの霜の石のせいで山頂は解けない。砕け",
"Wilde Mammuts": "野生のマンモス",
"Frostgeister": "霜の霊",
"In den Schneestürmen wandern Geister. Wer sie berührt, erfriert von innen": "吹雪の中を霊がさまよう。触れた者は内側から凍える",
"Der Eiskönig": "氷の王",
"Nebel über dem Moor": "沼にかかる霧",
"Das Totenmoor": "死者の沼",
"Moorwölfe": "沼狼",
"Die Wölfe hier sind halb tot und hören nicht auf zu jagen. Gib ihnen den Rest": "ここの狼は半ば死んでいるのに狩りをやめない。とどめを刺せ",
"Die Sumpfhexen": "沼の魔女たち",
"Hexen beschwören die Toten aus dem Schlamm. Ohne sie bleiben die Gräber zu": "魔女が泥から死者を呼び起こす。彼女らがいなければ墓は閉じたままだ",
"Zwei Steine der Fäulnis vergiften das Wasser. Nichts Lebendes wächst mehr": "二つの腐敗の石が水を毒している。生き物はもう育たない",
"Die Ghule fressen, was die Hexen erwecken. Sie sind schnell und hungrig. Sei schneller": "グールは魔女が起こしたものを喰らう。素早く飢えている。もっと速く動け",
"Donner in der Klamm": "峡谷の雷鳴",
"Oswin hat dich geschickt? Die Trolle belagern die Klamm. Zeig ihnen unsere Stärke": "オズウィンの差し金か？トロルが峡谷を包囲している。我らの力を見せてやれ",
"Harpyien": "ハーピーたち",
"Harpyien stoßen auf jeden herab, der den Pass hinaufsteigt. Hol sie aus der Luft": "峠を登る者にハーピーが襲いかかる。空から叩き落とせ",
"Die Minotauren": "ミノタウロスたち",
"Minotauren rennen mit gesenkten Hörnern gegen unsere Tore. Halte sie auf": "ミノタウロスが角を下げて門に突進してくる。止めろ",
"Blutrote Steine wachsen aus den Felsen. Sie nähren sich von Schmerz": "血のように赤い石が岩から生える。苦痛を糧にしている",
"Erwachte Titanen": "目覚めた巨人",
"Auf dem Titanenkamm stehen die Steintitanen auf. Bring sie wieder zum Stehen – für immer": "巨人の尾根で石の巨人が立ち上がる。止めてやれ――永遠に",
"Der Berg brennt": "山が燃える",
"Gunhild schickt dich? Dann bist du bereit. Golems aus Lava wälzen sich auf unser Lager zu": "グンヒルドの差し金か？なら準備はできている。溶岩のゴーレムが野営地に迫る",
"Glutkatzen": "熾火猫",
