"Zwei Steine der Flamme heizen den Berg an. Ohne sie verlöschen die Lavaflüsse": "二つの炎の石が山を熱している。それがなければ溶岩の川は消える",
"Feuerdämonen": "炎の悪魔",
"Aus den Kratern steigen Feuerdämonen. Treib sie zurück ins Feuer": "火口から炎の悪魔が昇ってくる。炎の中へ追い返せ",
"Feuerdrachen": "炎竜",
