"Sieben Tage in Folge abholen: Tag {0} bringt die Heldentruhe.": "7日連続で受け取ろう：{0}日目は英雄の宝箱。",
"Ab Stufe {0} trägt dich ein Drache über Hindernisse.": "レベル{0}から、ドラゴンが障害物を越えて運んでくれます。",
"Gemeinsam jagt es sich leichter: Gruppen teilen die Erfahrung.": "一緒に狩ると楽になる：パーティーは経験値を分け合います。",
"Im Turm der Verdammten warten ab Stufe {0} die stärksten Gegner.": "レベル{0}から、呪われし者の塔で最強の敵が待っています。",
"Werbung abgebrochen – keine Verdopplung.": "広告を中断しました。2倍にはなりません。",
"Belohnung verdoppelt": "報酬が2倍になりました",
"Hol dir jeden Tag die Tagesbelohnung – mit einer kurzen Werbung doppelt, am siebten Tag in Folge wartet die Heldentruhe": "毎日デイリー報酬を受け取ろう――短い広告で2倍、7日連続で英雄の宝箱が待っています",
